def _barras_senal(signal):
    try:
        nivel = min(4, max(1, math.ceil(float(signal) / 25)))
    except (TypeError, ValueError):
        nivel = 1
    barras = ''.join(
        f'<i class="{"on" if i <= nivel else ""}"></i>' for i in range(1, 5)
    )
    return f'<span class="bars" aria-hidden="true">{barras}</span>'


# ---------- HTML ----------

def generar_html_redes(redes):
    filas = ''
    for ssid, signal, security in redes:
        abierta = not security or security == '--'
        candado = '' if abierta else _LOCK_SVG
        filas += f"""
        <label class="net-row" data-abierta="{'1' if abierta else '0'}">
            <input type="radio" name="ssid" value="{ssid}" required>
            <span class="net-main">
                <span class="net-name">{ssid}</span>
                <span class="net-meta">{candado}<span>{signal}%</span></span>
            </span>
            {_barras_senal(signal)}
        </label>"""

    return f"""<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>LSD-Tector · Configuración</title>
<style>{CSS_BASE}</style>
</head>
<body>
    <div class="brand">
        <img src="data:image/png;base64,{_BIRD_ICON_B64}" alt="">
        <span class="brand-word">LSD <strong>Tector</strong></span>
    </div>
    <p class="eyebrow">Configuración Wi-Fi</p>
    <h1>Elegí la red Wi-Fi</h1>
    <p class="lead">El dispositivo se conectará a esta red en el sitio de instalación.</p>

    <form method="POST" action="/configurar">
        <div class="card">
            <div class="card-head">
                <span>Redes disponibles</span>
                <button type="button" class="icon-btn" onclick="location.reload()" aria-label="Actualizar lista de redes">{_REFRESH_SVG}</button>
            </div>
            {filas}
        </div>

        <div class="pass-wrap" id="password-wrap">
            <label class="field-label" for="password">Contraseña</label>
            <div class="pass-input">
                <input type="password" name="password" id="password" required>
                <button type="button" onclick="toggleMostrar()" aria-label="Mostrar contraseña">{_EYE_SVG}</button>
            </div>
        </div>

        <button type="submit" class="submit">Conectar</button>
    </form>

    <footer>LSD · Laboratorio de Sistemas Dinámicos, FCEyN UBA</footer>

    <script>
        function toggleMostrar() {{
            var pwd = document.getElementById('password');
            pwd.type = pwd.type === 'password' ? 'text' : 'password';
        }}
        function actualizarCampoPassword() {{
            var checked = document.querySelector('input[name="ssid"]:checked');
            var abierta = checked && checked.closest('.net-row').getAttribute('data-abierta') === '1';
            var wrap = document.getElementById('password-wrap');
            var pwd = document.getElementById('password');
            if (abierta) {{
                wrap.style.display = 'none';
                pwd.required = false;
                pwd.value = '';
            }} else {{
                wrap.style.display = '';
                pwd.required = true;
            }}
        }}
        document.querySelectorAll('input[name="ssid"]').forEach(function(r) {{
            r.addEventListener('change', actualizarCampoPassword);
        }});
        actualizarCampoPassword();
    </script>
</body>
</html>"""


